Here's a complete, well-commented TCP/IP echo server in C. It listens on a port, accepts a client, receives data, and echoes it back.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define BACKLOG 5  // Max pending connections

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];
    char client_ip[INET_ADDRSTRLEN];
    int opt = 1;

    // 1. Create TCP socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket() failed");
        exit(EXIT_FAILURE);
    }

    // 2. Allow address/port reuse (useful during development)
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) == -1) {
        perror("setsockopt() failed");
        exit(EXIT_FAILURE);
    }

    // 3. Configure server address structure
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;  // Listen on all available interfaces
    server_addr.sin_port = htons(PORT);        // Convert port to network byte order

    // 4. Bind socket to address & port
    if (bind(server_fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind() failed");
        exit(EXIT_FAILURE);
    }

    // 5. Mark socket as passive (listen for incoming connections)
    if (listen(server_fd, BACKLOG) == -1) {
        perror("listen() failed");
        exit(EXIT_FAILURE);
    }

    printf("TCP Server listening on port %d...\n", PORT);

    // 6. Accept & handle connections
    while (1) {
        client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
        if (client_fd == -1) {
            perror("accept() failed");
            continue;
        }

        // Convert client IP to readable string
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("New connection from %s:%d\n", client_ip, ntohs(client_addr.sin_port));

        // Communication loop for this client
        while (1) {
            memset(buffer, 0, BUFFER_SIZE);
            ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);

            if (bytes_received <= 0) {
                if (bytes_received == 0) {
                    printf("Client %s:%d disconnected.\n", client_ip, ntohs(client_addr.sin_port));
                } else {
                    perror("recv() error");
                }
                break; // Exit client loop, go back to accept()
            }

            buffer[bytes_received] = '\0'; // Null-terminate for safe printing
            printf("Received from %s: %s", client_ip, buffer);

            // Echo message back to client
            if (send(client_fd, buffer, bytes_received, 0) == -1) {
                perror("send() error");
                break;
            }
        }

        close(client_fd); // Close client connection before accepting next one
    }

    close(server_fd);
    return 0;
}
```

### 🔧 How to Compile & Run
```bash
# Compile
gcc -Wall -Wextra tcp_server.c -o tcp_server

# Run
./tcp_server

# Test from another terminal (Linux/macOS)
nc localhost 8080
# or
telnet localhost 8080
```

### 📖 How It Works
| Step | Function | Purpose |
|------|----------|---------|
| 1 | `socket()` | Creates an IPv4 TCP socket |
| 2 | `setsockopt()` | Enables `SO_REUSEADDR` to avoid "Address already in use" errors |
| 3 | `bind()` | Attaches socket to IP/port |
| 4 | `listen()` | Puts socket in passive mode, queues incoming connections |
| 5 | `accept()` | Blocks until a client connects, returns a new FD for communication |
| 6 | `recv()`/`send()` | Reads/writes data over the connected socket |

### ⚠️ Important Notes
1. **Single-Client Handling**: This server handles one client at a time. To support multiple clients concurrently, wrap the client-handling logic in:
   - `fork()` (process per client)
   - `pthread_create()` (thread per client)
   - `select()`/`poll()`/`epoll()` (event-driven I/O multiplexing)
2. **Windows Compatibility**: This uses POSIX sockets. On Windows, you'll need Winsock2 (`#include <winsock2.h>`), `WSAStartup()`, and replace `close()` with `closesocket()`.
3. **Production Considerations**:
   - Add timeouts (`setsockopt` with `SO_RCVTIMEO`)
   - Handle `SIGPIPE` (or use `send(..., MSG_NOSIGNAL)`)
   - Validate/sanitize input
   - Use non-blocking I/O + `epoll`/`kqueue` for high concurrency

Let me know if you want a **multi-client version** (using `fork`, `pthreads`, or `epoll`) or a **client code** to pair with this!

